using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static class B3Cleanup {public static object Run(){if(Application.isPlaying)throw new Exception("Edit required");var refs=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).ToArray();int count=0;foreach(string n in new[]{"BL_texture_mapping_LOD1","BL_texture_mapping_LOD2"}){string p="Assets/Afrer_Seconds/05.Model/Props/B3/"+n+".fbx";if(refs.Contains(p))throw new Exception("Still referenced "+p);if(AssetDatabase.LoadAssetAtPath<GameObject>(p)){if(!AssetDatabase.DeleteAsset(p))throw new Exception("Could not delete unused generated mesh");count++;}}return new{unusedDuplicateLodsRemoved=count};}}
